'use strict';
window.ATLAS = (() => {
const rev='ca1e85fe9430179831e6bc6be790c332190a3866';
const repo=`https://github.com/ace-step/ACE-Step-1.5/blob/${rev}/`;
const src=(path,label)=>({url:repo+path,label});
const sources={
 tutorial:src('docs/en/Tutorial.md','Developer tutorial'),
 inference:src('docs/en/INFERENCE.md','Python inference guide'),
 model:src('acestep/models/xl_base/modeling_acestep_v15_xl_base.py','XL Base model implementation'),
 config:src('acestep/models/common/configuration_acestep_v15.py','Architecture configuration'),
 embed:src('acestep/core/generation/handler/conditioning_embed.py','Conditioning embeddings'),
 lm:src('acestep/llm_inference.py','Language model inference'),
 vae:src('acestep/models/mlx/vae_model.py','Oobleck autoencoder implementation'),
 training:src('acestep/training_v2/trainer_vanilla.py','LoRA training implementation'),
 paper:{url:'https://arxiv.org/html/2602.00744v3',label:'ACE-Step 1.5 technical report'},
 flow:{url:'https://arxiv.org/abs/2210.02747',label:'Flow Matching for Generative Modeling'},
 fsq:{url:'https://arxiv.org/abs/2309.15505',label:'Finite Scalar Quantization'},
 mt3:{url:'https://github.com/magenta/mt3',label:'MT3 · multitrack transcription'},
 pitch:{url:'https://github.com/spotify/basic-pitch',label:'Basic Pitch · audio to MIDI'},
 xml:{url:'https://www.w3.org/2021/06/musicxml40/',label:'MusicXML 4.0 specification'},
 experiment:{url:'https://github.com/htansetiawan/maestro/tree/2002e29/experiments/002_ace_piano_vocals',label:'Your piano + voice experiment'}
};
const stages=[
 {name:'Inputs',tag:'Text + audio',title:'Specify intent. Supply musical context.',summary:'A caption and lyrics describe what to make. Source audio and a task decide which material to retain, reinterpret, or complement.',intuition:[
 ['Two different kinds of audio','src_audio is the material the selected task operates on. reference_audio is a separate style/timbre reference. Supplying one does not automatically supply the other. In your Lego run, the piano was source audio.'],
 ['Lyrics are a condition','Verse and chorus markers are text structure. The words are supplied to the model; their pitches, entrances, and syllable durations remain learned decisions unless an additional control mechanism constrains them.'],
 ['Metadata is a request','BPM, key, meter, and duration affect conditioning. A requested key or tempo is not a formal guarantee that every output note or beat satisfies it.']
 ],contract:{input:'Caption, lyrics, optional PCM audio',output:'Task + text tokens + source latents',rate:'Audio: 48,000 samples / second',meaning:'Human-readable intent; no note-event score'},tensor:'waveform: [B, 2, 48_000 × seconds]\nsource z: [B, ≈25 × seconds, 64]\ncaption tokens: [B, L_text]\nlyric tokens: [B, L_lyrics]',code:'GenerationParams(\n    task_type="lego",\n    src_audio="piano.wav",\n    lyrics=lyrics,\n    caption="Warm intimate male tenor…",\n    thinking=False,\n)',research:'A source recording bundles melody, harmony, rubato, and timbre. To enforce a particular lead melody, first identify that musical voice and represent its note events. Merely conditioning on a polyphonic piano performance leaves this choice ambiguous.',refs:['inference','experiment']},
 {name:'Planner',tag:'Optional LM',title:'Plan in a discrete acoustic vocabulary.',summary:'The optional Qwen-based LM predicts metadata and 5 Hz audio codes. These codes guide acoustic structure; they are not a MIDI score.',intuition:[
 ['Autoregressive planning','The LM predicts the next token from prior tokens and text context. CoT metadata and acoustic token generation are related capabilities with separate inference flags; switching off metadata rewriting is not identical to removing all audio-code conditioning.'],
 ['The acoustic vocabulary','Five 25 Hz latent frames are pooled and quantized using finite scalar quantization. The configured scalar levels are [8, 8, 8, 5, 5, 5], giving 64,000 possible index combinations. A code represents a learned acoustic neighborhood, not a named note.'],
 ['Multiple routes into the next stage','Codes may be generated by the LM or extracted from source audio. In the recorded Lego experiment, thinking and every CoT flag were off, and audio_codes was empty. Source conditioning still reached the DiT.']
 ],contract:{input:'Text context or quantized source audio',output:'Metadata + discrete acoustic codes',rate:'5 codes / second · 200 ms per code',meaning:'Learned structure; no pitch-name semantics'},tensor:'code IDs: [B, ≈5 × seconds]\nFSQ combinations: 8³ × 5³ = 64,000\npooled embeddings: 25 Hz → 5 Hz\ndetokenized hints: 5 Hz → 25 Hz',code:'# Model boundary; requires a loaded checkpoint\nquantized, indices, mask = model.tokenize(\n    source_z, silence_latent, attention_mask\n)\nhints_25Hz = model.detokenize(quantized)\n# LM-generated IDs use FSQ lookup before detokenizing.',research:'Train probes for pitch, harmony, onset, and instrument identity. Then test interventions: changing a code or direction must change the intended attribute while preserving others. A successful linear probe shows decodability, not causal control or disentanglement.',refs:['lm','model','fsq','tutorial']},
 {name:'Conditions',tag:'Encode + fuse',title:'Bring language, lyrics, and sound together.',summary:'Caption representations, lyric embeddings, and reference timbre features form encoder states. Source latents and masks form a separate time-aligned context.',intuition:[
 ['Text paths are distinct','The handler obtains caption hidden states from its text encoder and lyric token embeddings from that encoder’s embedding table. Dedicated model encoders process the lyric and timbre branches before conditioning the DiT.'],
 ['Cross-attention','Queries from the evolving acoustic representation attend to encoded caption, lyric, and timbre information. Attention can be inspected for alignment behavior, but its weights alone are not a complete causal explanation.'],
 ['Source plus mask','prepare_condition returns encoder_hidden_states and context_latents. It concatenates source latents and chunk masks; for code-conditioned paths, detokenized hints can replace the source context.']
 ],contract:{input:'Text/lyric embeddings + source/reference features',output:'Encoder states + time-aligned context',rate:'Source context aligned to 25 Hz',meaning:'Conditioning memory, not rendered audio'},tensor:'text embedding width: 1,024 in XL config\nencoder hidden width: 2,048\nsource: [B, T, 64]\nmask: [B, T, 64]\ncontext = concat(source, mask): [B, T, 128]',code:'# prepare_condition, simplified\nencoder_states, encoder_mask = model.encoder(…)\nsource = select_source_or_detokenized_hints(…)\ncontext = torch.cat([source, chunk_mask], dim=-1)\n# The noised target adds another 64 channels\n# to the DiT input: 64 + 64 + 64 = 192.',research:'A symbolic adapter could add note, beat, chord, or syllable features at this boundary. This is a proposed modification requiring training and evaluation, not an existing stock MIDI-input contract.',refs:['embed','model','config']},
 {name:'Flow matching',tag:'DiT sampling',title:'Integrate a learned velocity field.',summary:'Start from seeded Gaussian noise, then solve a learned conditional transport path toward acoustic latents. This happens in compressed space, not directly in the waveform.',intuition:[
 ['The convention in this implementation','t = 1 is noise and t = 0 is clean data. Training samples zₜ = (1 − t)z_data + tε and fits vθ to ε − z_data. Inference integrates toward decreasing t. Other papers may use the opposite time convention.'],
 ['Transformer on acoustic patches','The noised target, source, and mask comprise 192 input channels in the inspected XL configuration. A patch size of two reduces the 25 Hz frame sequence to a 12.5 Hz transformer sequence; output is unpatched to latent frames.'],
 ['Guidance and checkpoint matter','Base supports classifier-free guidance. Turbo is distilled for fewer steps and does not use ordinary CFG in the inference pipeline. Your take used XL Base, 50 steps, and guidance 7.0; do not transfer these settings blindly to Turbo.']
 ],contract:{input:'Gaussian z₁ + conditions + source/mask',output:'Predicted acoustic latent z₀',rate:'25 Hz latent · 12.5 Hz patched sequence',meaning:'Velocity field over acoustic coordinates'},tensor:'zₜ = (1 − t)z_data + tε\nv_target = ε − z_data\nL = E[‖vθ(zₜ, t, c) − v_target‖²]\nz_next = z + (t_next − t) vθ\nt: 1 → 0',code:'# Euler step, conceptual; decreasing time\nv = dit(z, t, condition)\n# Base CFG: v = v_null + s * (v_cond - v_null)\nz = z + (t_next - t) * v\n# Repeat over the selected timestep schedule.',research:'Freeze prompt and seed, then edit one condition at a time. Log latents along the trajectory; measure which edits change pitch, onset, timbre, or arrangement. Guidance strength is not a pitch-preservation constraint.',refs:['model','flow','inference']},
 {name:'Acoustic latent',tag:'25 Hz × 64',title:'A compressed signal, with entangled meaning.',summary:'The final acoustic representation has 64 continuous channels at roughly 25 frames per second. Those channels carry information needed to reconstruct sound, without named musical roles.',intuition:[
 ['Compression is not interpretation','At 48 kHz stereo, each second holds 96,000 waveform values. At 25 Hz × 64, it holds about 1,600 latent values. This is a dimensional reduction of 60×, not a bitrate calculation or a claim of lossless compression.'],
 ['What each frame spans','The configured Oobleck downsampling ratios multiply to 1,920. At 48,000 Hz that corresponds to a 40 ms frame hop. Padding and convolution boundaries can change exact sequence lengths.'],
 ['Keep the representations separate','PCM samples, 64-channel acoustic latents, FSQ code IDs, and symbolic note events are different objects. There is no stock rule that channel 7 is pitch, nor that adding one to a code transposes a semitone.']
 ],contract:{input:'DiT output or VAE-encoded source',output:'Continuous decoder input',rate:'25 frames / second · 40 ms hop',meaning:'Acoustic information without declared note semantics'},tensor:'z: [B, T_latent, 64]\nT_latent ≈ seconds × 25\n48,000 / (2×4×4×6×10) = 25 Hz\n25 × 64 = 1,600 values per second',code:'# Observed VAE configuration\naudio_channels = 2\nsampling_rate = 48_000\ndecoder_input_channels = 64\ndownsampling_ratios = [2, 4, 4, 6, 10]',research:'First benchmark encode→decode reconstruction with real audio. Pitch and rhythm changes caused by the codec set a floor for downstream round-trip fidelity. Preserve provenance and uncertainty instead of assigning invented musical labels to latent dimensions.',refs:['vae','config','model']},
 {name:'Waveform',tag:'Decode + export',title:'Turn the representation into audible music.',summary:'The waveform autoencoder decodes continuous latents to stereo audio. Export, mixing, and listening happen after neural generation.',intuition:[
 ['The final synthesis stage','The Oobleck decoder upsamples the continuous representation back to 48 kHz audio. Decoding is a separate learned mapping from the LM and the flow model; inspecting the final WAV alone hides these intermediate decisions.'],
 ['Generation versus mixing','Your experiment decoded a vocal stem and added it to the original piano with a measured gain. Sixteen milliseconds of silence matched the source duration. No note-level retiming, pitch correction, or melody matching was performed.'],
 ['Verify the musical contract','Finite samples and no clipping check signal validity. ASR checks word recovery. Pitch/onset analysis, source preservation measurements, and listening are separate checks that were not established by that initial run.']
 ],contract:{input:'Continuous acoustic latent',output:'48 kHz stereo PCM → WAV / MP3',rate:'48,000 samples / second / channel',meaning:'Sound; score reconstruction is a separate task'},tensor:'decoder input: [B, 64, T_latent]\nPCM output: [B, 2, N_samples]\nmix = piano + gain × vocal\nexport ≠ pitch/onset verification',code:'# Actual mix logic in the recorded experiment\nvocal_gain = piano_rms / vocal_rms * 10 ** (2 / 20)\nmix = piano + vocal * vocal_gain\nmix_gain = min(1.0, .95 / max(abs(mix).max(), 1e-8))',research:'Make round-trip tests explicit: audio→events→score→performance→audio. Evaluate note identity, onset/offset error, voice assignment, notation structure, timbre, and human editability separately. A plausible recording does not establish faithful transcription.',refs:['vae','experiment','pitch','mt3']}
];
const lessons=[
 {title:'1. Codec reconstruction',question:'What is already lost before generation?',text:'Encode and decode a short clean piano phrase. Save the input, latent, reconstruction, and exact revisions. Compare onsets, pitch tracks, transients, and waveform residuals.',deliver:'A reconstruction baseline with musical error measurements.',refs:['vae']},
 {title:'2. Codes versus acoustics',question:'Where does structure survive compression?',text:'Tokenize that latent into FSQ codes, detokenize, and compare downstream reconstructions against direct continuous conditioning. Probe pitch classes, note density, and beats at both resolutions.',deliver:'A representation table with rate, recoverability, and uncertainty.',refs:['model','fsq']},
 {title:'3. Condition ablations',question:'Which input actually controls which property?',text:'Fix seed, source, checkpoint, schedule, and duration. Vary only captions, lyrics, reference timbre, or code hints. Use several seeds after the paired baseline to estimate variance.',deliver:'An ablation matrix separating pitch, rhythm, timbre, and lyric adherence.',refs:['inference']},
 {title:'4. Causal latent edits',question:'Does a decodable attribute become an editable one?',text:'Fit a pitch probe on held-out phrases. Intervene along its direction, decode, and check target changes and collateral timbre/onset changes. Compare against a trivial waveform or MIDI transposition baseline.',deliver:'A causal edit curve, with preservation costs and failure examples.',refs:['flow']},
 {title:'5. A symbolic adapter',question:'Can explicit note contracts improve controllability?',text:'Build aligned score, performed MIDI, audio, lyrics, and confidence records. Train a score-condition encoder or constrained renderer. Compare with stock prompt/source conditioning on held-out melodies.',deliver:'An executable musical IR and a renderer with measured constraint fidelity.',refs:['xml','mt3']}
];
return {rev,repo,sources,stages,lessons};
})();
